const OVER_LIMIT_LINK_IDS = [999000001, 999000002, 999000003, 999000004, 999000005, 999000006, 999000007, 999000008, 999000009, 999000010, 999000011, 999000012, 999000013, 999000014, 999000015, 999000016, 999000017, 999000018, 999000019, 999000020, 999000021, 999000022, 999000023, 999000024, 999000025, 999000026, 999000027, 999000028, 999000029, 999000030, 999000031, 999000032, 999000033, 999000034, 999000035, 999000036, 999000037, 999000038, 999000039, 999000040, 999000041, 999000042, 999000043, 999000044, 999000045, 999000046, 999000047, 999000048, 999000049, 999000050, 999000051, 999000052, 999000053, 999000054, 999000055, 999000056, 999000057, 999000058, 999000059, 999000060, 999000061, 999000062, 999000063, 999000064, 999000065, 999000066, 999000067, 999000068, 999000069, 999000070, 999000071, 999000072, 999000073, 999000074, 999000075, 999000076, 999000077, 999000078, 999000079, 999000080, 999000081, 999000082, 999000083, 999000084, 999000085, 999000086, 999000087, 999000088, 999000089, 999000090, 999000091, 999000092, 999000093, 999000094, 999000095, 999000096, 999000097, 999000098, 999000099, 999000100, 999000101];
// Exactly 100 ids is inside the documented maximum. None of them is owned by the caller.
const AT_LIMIT_LINK_IDS = [999000001, 999000002, 999000003, 999000004, 999000005, 999000006, 999000007, 999000008, 999000009, 999000010, 999000011, 999000012, 999000013, 999000014, 999000015, 999000016, 999000017, 999000018, 999000019, 999000020, 999000021, 999000022, 999000023, 999000024, 999000025, 999000026, 999000027, 999000028, 999000029, 999000030, 999000031, 999000032, 999000033, 999000034, 999000035, 999000036, 999000037, 999000038, 999000039, 999000040, 999000041, 999000042, 999000043, 999000044, 999000045, 999000046, 999000047, 999000048, 999000049, 999000050, 999000051, 999000052, 999000053, 999000054, 999000055, 999000056, 999000057, 999000058, 999000059, 999000060, 999000061, 999000062, 999000063, 999000064, 999000065, 999000066, 999000067, 999000068, 999000069, 999000070, 999000071, 999000072, 999000073, 999000074, 999000075, 999000076, 999000077, 999000078, 999000079, 999000080, 999000081, 999000082, 999000083, 999000084, 999000085, 999000086, 999000087, 999000088, 999000089, 999000090, 999000091, 999000092, 999000093, 999000094, 999000095, 999000096, 999000097, 999000098, 999000099, 999000100];

// The body carries no linkIds key at all, so it cannot be expressed as a dataOverride on the
// shared createBulkArchiveJob helper - the request differs structurally, not by literal.
async function createBulkArchiveJobWithoutLinkIds(
    client: SkyrampClient,
    headers: Record<string, string>,
    expectedStatus = 400
) {
    // Request Body
    const bulkArchivePost1RequestBody: string = `{
        "ids": [
            999000001
        ]
    }`;

    // Execute Request
    const bulkArchivePost1Response = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/links/bulk-archive",
        method: "POST",
        body: bulkArchivePost1RequestBody,
        headers: headers
    });

    // Generated Assertions
    expect(bulkArchivePost1Response.statusCode, 'status code').toBe(expectedStatus);

    return bulkArchivePost1Response;
}

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const linkName = "Bulk archive validation link";
    const linkUrl = uniqueSuffix("https://example.com/bulk-archive-validation");
    const collectionName = uniqueSuffix("Bulk Archive Validation");

    // The accepted request succeeds before any rejection is asserted.
    const linksPostResponse = await createLink(client, headers, linkName, linkUrl, collectionName);

    const linkId = getResponseValue(linksPostResponse, "response.id");
    const collectionId = getResponseValue(linksPostResponse, "response.collection.id");
    expect(linkId, 'created link id').not.toBeNull();
    expect(getResponseValue(linksPostResponse, "response.url"), 'created link url').toBe(linkUrl);

    // "Returns 400 if linkIds is empty or exceeds 100 items."
    const bulkArchivePostResponse = await createBulkArchiveJob(client, headers, [], 400);
    expect(bulkArchivePostResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(bulkArchivePostResponse, "response"), 'empty array rejection message')
        .toBe("linkIds array is required.");
    expect(getResponseValue(bulkArchivePostResponse, "response.jobId"), 'no job for a rejected batch').toBeNull();

    // A body with no linkIds key is rejected the same way.
    const bulkArchivePost1Response = await createBulkArchiveJobWithoutLinkIds(client, headers);
    expect(bulkArchivePost1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(bulkArchivePost1Response, "response"), 'missing linkIds rejection message')
        .toBe("linkIds array is required.");
    expect(getResponseValue(bulkArchivePost1Response, "response.jobId"), 'no job for a rejected batch').toBeNull();

    // 101 items exceeds the documented maximum.
    const bulkArchivePost2Response = await createBulkArchiveJob(client, headers, OVER_LIMIT_LINK_IDS, 400);
    expect(bulkArchivePost2Response.statusCode, 'status code').toBe(400);
    expect(OVER_LIMIT_LINK_IDS.length, 'over-limit batch size').toBe(101);
    expect(getResponseValue(bulkArchivePost2Response, "response"), 'over-limit rejection message')
        .toBe("Maximum 100 links per batch.");
    expect(getResponseValue(bulkArchivePost2Response, "response.jobId"), 'no job for a rejected batch').toBeNull();

    // Exactly 100 items does NOT exceed the maximum, so the length gate lets it through and the
    // ownership gate answers instead - a 400 here would mean the boundary is off by one.
    const bulkArchivePost3Response = await createBulkArchiveJob(client, headers, AT_LIMIT_LINK_IDS, 403);
    expect(bulkArchivePost3Response.statusCode, 'status code').toBe(403);
    expect(AT_LIMIT_LINK_IDS.length, 'at-limit batch size').toBe(100);
    expect(getResponseValue(bulkArchivePost3Response, "response"), 'at-limit ownership rejection message')
        .toBe("One or more links are not accessible.");
    expect(getResponseValue(bulkArchivePost3Response, "response.jobId"), 'no job for a rejected batch').toBeNull();

    // A non-numeric entry is malformed input. The repository rejects a malformed body with 400
    // (see the schema-validation branch in apps/web/pages/api/v1/rss/index.ts), not a 5xx.
    const bulkArchivePost4Response = await createBulkArchiveJob(client, headers, ["abc"], 400);
    expect(bulkArchivePost4Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(bulkArchivePost4Response, "response"), 'non-numeric rejection message')
        .toBe("linkIds array is required.");
    expect(getResponseValue(bulkArchivePost4Response, "response.jobId"), 'no job for a rejected batch').toBeNull();

    // A non-POST method is rejected.
    const bulkArchiveGetResponse = await getBulkArchive(client, headers, 405);
    expect(bulkArchiveGetResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(bulkArchiveGetResponse, "response"), 'method rejection message')
        .toBe("Method not allowed.");

    const linksLinksDeleteResponse = await deleteLink(client, headers, linkId);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link id').toBe(linkId);

    const collectionsDeleteResponse = await deleteCollection(client, headers, collectionId);
    expect(getResponseValue(collectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(collectionId);
});
